import { createContext, useContext, useEffect, useState } from "react";
import { supabase } from "../lib/supabase";

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  // Загружаем профиль из БД
  const loadProfile = async (userId) => {
    const { data, error } = await supabase
      .from("profiles")
      .select("*")
      .eq("id", userId)
      .single();

    if (error) {
      console.error("Ошибка загрузки профиля:", error.message);
      return null;
    }
    return data;
  };

  useEffect(() => {
    // 1. Проверяем текущую сессию
    supabase.auth.getSession().then(async ({ data: { session } }) => {
      setUser(session?.user ?? null);
      if (session?.user) {
        const p = await loadProfile(session.user.id);
        setProfile(p);
      }
      setLoading(false);
    });

    // 2. Слушаем изменения авторизации
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (_event, session) => {
      setUser(session?.user ?? null);
      if (session?.user) {
        const p = await loadProfile(session.user.id);
        setProfile(p);
      } else {
        setProfile(null);
      }
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const signUp = async (email, password, username) => {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          username,
          display_name: username,
        },
      },
    });
    return { data, error };
  };

  const signIn = async (email, password) => {
    return supabase.auth.signInWithPassword({ email, password });
  };

  const signOut = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setProfile(null);
  };

  const refreshProfile = async () => {
    if (!user) return;
    const p = await loadProfile(user.id);
    setProfile(p);
  };

  const updateProfile = async (updates) => {
    if (!user) return { error: "Не авторизован" };

    const { data, error } = await supabase
      .from("profiles")
      .update(updates)
      .eq("id", user.id)
      .select()
      .single();

    if (!error) setProfile(data);
    return { data, error };
  };

  const uploadImage = async (file, bucket) => {
    // Получаем актуального пользователя из сессии
    const {
      data: { user: currentUser },
    } = await supabase.auth.getUser();
    if (!currentUser) return { error: new Error("Не авторизован") };

    const fileExt = file.name.split(".").pop() || "jpg";
    const filePath = `${currentUser.id}/${Date.now()}.${fileExt}`;

    const { error: uploadError } = await supabase.storage
      .from(bucket)
      .upload(filePath, file, {
        upsert: true,
        contentType: file.type,
      });

    if (uploadError) return { error: uploadError };

    const {
      data: { publicUrl },
    } = supabase.storage.from(bucket).getPublicUrl(filePath);

    return { url: publicUrl };
  };

  const value = {
    user,
    profile,
    loading,
    signUp,
    signIn,
    signOut,
    updateProfile,
    uploadImage,
    refreshProfile,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
};

import { createContext, useContext, useState, useEffect } from "react";
import { getAvailableFilters } from "../lib/materials";

const FilterContext = createContext(null);

export const FilterProvider = ({ children }) => {
  const availableFilters = getAvailableFilters();

  // Выбранный курс — по умолчанию первый
  const [courseId, setCourseId] = useState(
    () =>
      localStorage.getItem("filter-course") ||
      availableFilters[0]?.id ||
      "course-1",
  );

  // Выбранный семестр — по умолчанию первый семестр выбранного курса
  const [semesterId, setSemesterId] = useState(() => {
    const saved = localStorage.getItem("filter-semester");
    if (saved) return saved;
    const course = availableFilters.find((c) => c.id === courseId);
    return course?.semesters[0]?.id || "semester-1";
  });

  // Синхронизация с localStorage
  useEffect(() => {
    localStorage.setItem("filter-course", courseId);
  }, [courseId]);

  useEffect(() => {
    localStorage.setItem("filter-semester", semesterId);
  }, [semesterId]);

  // При смене курса — переключаем семестр на первый доступный
  const changeCourse = (newCourseId) => {
    setCourseId(newCourseId);
    const course = availableFilters.find((c) => c.id === newCourseId);
    setSemesterId(course?.semesters[0]?.id || "semester-1");
  };

  const value = {
    courseId,
    semesterId,
    setSemesterId,
    changeCourse,
    availableFilters,
  };

  return (
    <FilterContext.Provider value={value}>{children}</FilterContext.Provider>
  );
};

export const useFilter = () => {
  const ctx = useContext(FilterContext);
  if (!ctx) throw new Error("useFilter must be used within FilterProvider");
  return ctx;
};

import { createContext, useContext } from "react";
import { useAuth } from "./AuthContext";
import { usePresence } from "../hooks/usePresence";

const PresenceContext = createContext(new Set());

export const PresenceProvider = ({ children }) => {
  const { user, profile } = useAuth();
  const onlineUsers = usePresence(user, profile);

  return (
    <PresenceContext.Provider value={onlineUsers}>
      {children}
    </PresenceContext.Provider>
  );
};

export const useOnlineUsers = () => useContext(PresenceContext);

import { createContext, useContext, useEffect, useState } from "react";

const ThemeContext = createContext(null);

export const ThemeProvider = ({ children }) => {
  // 'dark' | 'light'
  const [theme, setTheme] = useState(() => {
    const saved = localStorage.getItem("theme");
    if (saved === "light" || saved === "dark") return saved;

    // По умолчанию — системная тема
    if (window.matchMedia?.("(prefers-color-scheme: light)").matches) {
      return "light";
    }
    return "dark";
  });

  // Применяем к <html data-theme="...">
  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    localStorage.setItem("theme", theme);

    // Меняем цвет адресной строки на мобильных
    const metaTheme = document.querySelector('meta[name="theme-color"]');
    if (metaTheme) {
      metaTheme.setAttribute(
        "content",
        theme === "light" ? "#f5f6fa" : "#0f1115",
      );
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prev) => (prev === "dark" ? "light" : "dark"));
  };

  const setThemeValue = (value) => {
    if (value === "dark" || value === "light") setTheme(value);
  };

  return (
    <ThemeContext.Provider
      value={{ theme, toggleTheme, setTheme: setThemeValue }}
    >
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error("useTheme must be used within ThemeProvider");
  return ctx;
};

